export const SPLASH_HTML: string = "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\"/>\n<title>Splash — Tableau des maladies professionnelles · Maroc</title>\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"/>\n<meta name=\"theme-color\" content=\"#15294a\"/>\n<style>\n  *,*::before,*::after { box-sizing: border-box; }\n  html, body { margin: 0; padding: 0; height: 100%; background: #15294a; overflow: hidden; }\n  body {\n    font-family: -apple-system, \"SF Pro\", BlinkMacSystemFont, \"Segoe UI\", system-ui, sans-serif;\n    -webkit-font-smoothing: antialiased;\n    color: #fff;\n    user-select: none;\n    -webkit-user-select: none;\n  }\n  /* Stage — fills the viewport, contains the splash */\n  .splash {\n    position: fixed; inset: 0;\n    background: radial-gradient(120% 80% at 50% 100%, #15294a 0%, #28518A 70%);\n    overflow: hidden;\n    display: flex; flex-direction: column;\n    align-items: center; justify-content: center;\n  }\n  /* Decorative orbs */\n  .orb { position: absolute; border-radius: 50%; }\n  .orb-1 { top: -12%; left: -15%; width: 320px; height: 320px; background: rgba(255,255,255,0.06); }\n  .orb-2 { bottom: -18%; right: -25%; width: 380px; height: 380px; background: rgba(255,255,255,0.05); }\n\n  /* Halo — pulses with the heartbeat */\n  .halo {\n    position: absolute; top: 42%; left: 50%;\n    width: min(90vw, 480px); aspect-ratio: 1;\n    transform: translate(-50%, -50%);\n    background: radial-gradient(circle, rgba(150,200,255,0.22) 0%, rgba(150,200,255,0) 55%);\n    filter: blur(6px);\n    pointer-events: none;\n    animation: halo 1.6s ease-in-out infinite;\n  }\n  @keyframes halo {\n    0%, 60%, 100% { transform: translate(-50%, -50%) scale(1); opacity: .55; }\n    14% { transform: translate(-50%, -50%) scale(1.06); opacity: 1; }\n    30% { transform: translate(-50%, -50%) scale(1.03); opacity: .8; }\n  }\n\n  /* Content stack */\n  .content {\n    position: relative;\n    display: flex; flex-direction: column;\n    align-items: center; justify-content: center;\n    gap: 28px;\n    padding-bottom: 40px;\n    width: 100%;\n  }\n\n  /* Badge area */\n  .badge-wrap {\n    position: relative;\n    width: min(78vw, 360px);\n    aspect-ratio: 1;\n    display: flex; align-items: center; justify-content: center;\n    animation: intro 0.9s cubic-bezier(.2,.7,.3,1.4) both;\n  }\n  @keyframes intro {\n    from { transform: scale(.55); opacity: 0; }\n    to   { transform: scale(1);   opacity: 1; }\n  }\n\n  .badge {\n    position: relative; width: 100%; aspect-ratio: 1;\n    animation: heartbeat 1.6s ease-in-out infinite;\n    animation-delay: 0.9s;\n  }\n  @keyframes heartbeat {\n    0%, 60%, 100% { transform: scale(1); }\n    14% { transform: scale(1.045); }\n    22% { transform: scale(1.005); }\n    30% { transform: scale(1.030); }\n    40% { transform: scale(1.000); }\n  }\n\n  .disc {\n    position: absolute; inset: 14%; border-radius: 50%;\n    background: #fff;\n    box-shadow: 0 22px 50px rgba(0,0,0,.32), 0 0 0 1px rgba(255,255,255,.08);\n  }\n  .logo {\n    width: 148%; height: 148%;\n    position: absolute; top: -24%; left: -24%;\n    object-fit: contain;\n    pointer-events: none;\n  }\n\n  /* Pulse rings — emit on lub and dub */\n  .ring {\n    position: absolute;\n    width: 88%; aspect-ratio: 1;\n    border-radius: 50%;\n    border: 1.5px solid rgba(255,255,255,.85);\n    opacity: 0;\n    animation: ringPulse 1.6s ease-out infinite;\n    animation-delay: 0.9s;\n  }\n  .ring.dub { animation-delay: 1.16s; }\n  @keyframes ringPulse {\n    0%   { transform: scale(1);    opacity: .55; }\n    100% { transform: scale(2.35); opacity: 0; }\n  }\n\n  /* Text */\n  .text {\n    text-align: center;\n    padding-inline: 24px;\n    animation: rise 0.7s ease-out 0.4s both;\n  }\n  @keyframes rise {\n    from { opacity: 0; transform: translateY(14px); }\n    to   { opacity: 1; transform: translateY(0); }\n  }\n  .eyebrow {\n    font-size: 11px; opacity: .55; letter-spacing: 5px;\n    text-transform: uppercase; margin-bottom: 12px; font-weight: 500;\n  }\n  .title {\n    font-size: clamp(20px, 5.5vw, 26px);\n    font-weight: 700; letter-spacing: -0.2px; line-height: 1.18;\n  }\n  .region {\n    font-size: 14px; opacity: .7; font-weight: 500; margin-top: 4px;\n    letter-spacing: .3px;\n  }\n  .ar {\n    font-size: clamp(15px, 4.5vw, 19px);\n    opacity: .88; margin-top: 14px; font-weight: 600;\n    line-height: 1.3;\n    font-family: system-ui, \"Segoe UI\", \"Tahoma\", sans-serif;\n  }\n\n  /* ECG baseline */\n  .ecg {\n    position: absolute;\n    bottom: max(40px, env(safe-area-inset-bottom));\n    left: 50%; transform: translateX(-50%);\n    width: 200px; height: 28px;\n    opacity: 0;\n    animation: ecgFadeIn .5s ease-out 1s forwards;\n  }\n  @keyframes ecgFadeIn { to { opacity: .7; } }\n  .ecg svg { width: 100%; height: 100%; display: block; }\n  .ecg .spike {\n    transform-origin: 90px 12px;\n    animation: ecgSweep 1.6s linear infinite;\n    animation-delay: .9s;\n  }\n  @keyframes ecgSweep {\n    0%   { transform: translateX(-90px); }\n    100% { transform: translateX(110px); }\n  }\n\n  /* When user prefers reduced motion, freeze everything */\n  @media (prefers-reduced-motion: reduce) {\n    .badge-wrap, .badge, .ring, .halo, .text, .ecg, .ecg .spike {\n      animation: none !important;\n    }\n  }\n</style>\n</head>\n<body>\n  <main class=\"splash\" role=\"img\" aria-label=\"Tableau des maladies professionnelles — Maroc · جدول الأمراض المهنية بالمغرب\">\n    <div class=\"orb orb-1\"></div>\n    <div class=\"orb orb-2\"></div>\n    <div class=\"halo\"></div>\n\n    <div class=\"content\">\n      <div class=\"badge-wrap\">\n        <span class=\"ring lub\"></span>\n        <span class=\"ring dub\"></span>\n        <div class=\"badge\">\n          <div class=\"disc\"></div>\n          <img class=\"logo\" src=\"data:image/png;base64,\" alt=\"\"/>\n        </div>\n      </div>\n\n      <div class=\"text\">\n        <div class=\"eyebrow\">Santé et sécurité au travail</div>\n        <div class=\"title\">Tableau des maladies<br/>professionnelles</div>\n        <div class=\"region\">Maroc</div>\n        <div class=\"ar\" dir=\"rtl\">جدول الأمراض المهنية<br/>بالمغرب</div>\n      </div>\n    </div>\n\n    <div class=\"ecg\" aria-hidden=\"true\">\n      <svg viewBox=\"0 0 200 28\" preserveAspectRatio=\"none\">\n        <defs>\n          <linearGradient id=\"ecgFade\" x1=\"0\" x2=\"1\">\n            <stop offset=\"0\" stop-color=\"#fff\" stop-opacity=\"0\"/>\n            <stop offset=\".2\" stop-color=\"#fff\" stop-opacity=\".7\"/>\n            <stop offset=\".8\" stop-color=\"#fff\" stop-opacity=\".7\"/>\n            <stop offset=\"1\" stop-color=\"#fff\" stop-opacity=\"0\"/>\n          </linearGradient>\n        </defs>\n        <line x1=\"0\" y1=\"14\" x2=\"200\" y2=\"14\" stroke=\"url(#ecgFade)\" stroke-width=\"1.2\"/>\n        <g class=\"spike\">\n          <path d=\"M80 14 L86 5 L90 22 L94 11 L100 14\"\n            fill=\"none\" stroke=\"#fff\" stroke-width=\"1.6\"\n            stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n        </g>\n      </svg>\n    </div>\n  </main>\n</body>\n</html>";